steps.code:
# Let's fetch all trip group details and store member mappings
sw_token = splitwise_login['access_token']
trip_group_ids = {3084: 274, 3085: 275, 3086: 276, 3087: 277, 3088: 278}
group_members = {}
for gid in trip_group_ids.values():
    group = apis.splitwise.show_group(access_token=sw_token, group_id=gid)
    # Build first-name -> email mapping
    name_to_email = {}
    for m in group['members']:
        first = m['name'].split()[0]
        name_to_email[first] = m['email']
    group_members[gid] = name_to_email
    print(f"Group {gid}: {name_to_email}")

