# Let's verify expenses for all 5 trip groups by checking their expenses
trip_group_ids = [274, 275, 276, 277, 278]
for gid in trip_group_ids:
    expenses = apis.splitwise.show_group_expenses(access_token=sw_token, group_id=gid, page_limit=20)
    print(f"Group {gid}: {len(expenses) if isinstance(expenses, list) else expenses} expenses")
    if isinstance(expenses, list):
        for e in expenses:
            print(f"  {e['expense_id']}: {e['description']} - {e['paid_amount']} by {e['payer']['email']}")

